import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { z } from 'zod'
import { loginConfiguration } from './login-config'

// One .env at the repository root holds this working copy's ports and database,
// generated by bin/init-env.sh. It is absent in CI, where the values come from the
// environment itself.
try {
  process.loadEnvFile(fileURLToPath(new URL('../../.env', import.meta.url)))
} catch {
  // no .env in this environment — fall through to process.env
}

const envSchema = z.object({
  API_PORT: z.coerce.number().int().positive().default(3300),
  DATABASE_URL: z.string().min(1),
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  /**
   * The hourly refresh of official rates (MOL-39), which goes out to the central banks. On by
   * default, so production cannot forget it; end-to-end runs switch it off, because a test that
   * depends on a foreign server answering is a test that fails for someone else's reasons.
   */
  RATES_REFRESH: z.enum(['on', 'off']).default('on'),
  /**
   * The build `/health` names (MOL-90): `git describe` of the commit the image was built from —
   * `v0.1.1-3-g1a2b3c4`, or the tag alone on a tagged commit. The image carries it; outside one it
   * is `dev`. What the deploy compares with to know the new containers are the ones answering.
   */
  APP_VERSION: z.string().min(1).default('dev'),
})

export const env = envSchema.parse(process.env)
export const VERSION = env.APP_VERSION

export const loginConfig = loginConfiguration(process.env)
